{
  "name": "单色仪",
  "name_en": "Monochromator",
  "manufacturer": "HORIBA",
  "description": "用于将复色光按波长分散并选出窄带光的光学单色仪。该设备通常包含光栅转塔、狭缝、滤光轮、反射镜和快门，可在光谱测量与其他光学实验中进行波长扫描、带宽调节和光路切换。",
  "description_en": "An optical monochromator that disperses polychromatic light and selects a narrow wavelength band. The device typically includes a grating turret, slits, filter wheels, mirrors, and shutters, and is used in spectroscopy and other optical experiments for wavelength scanning, bandwidth adjustment, and beam-path selection.",
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开与单色仪的连接。",
      "description_en": "Open the connection to the monochromator."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与单色仪的连接。",
      "description_en": "Close the connection to the monochromator."
    },
    {
      "action_name": "auto-is_open",
      "description": "检查与单色仪的连接是否已打开。",
      "description_en": "Check whether the connection to the monochromator is open."
    },
    {
      "action_name": "auto-is_busy",
      "description": "检查单色仪当前是否忙碌。",
      "description_en": "Check whether the monochromator is currently busy."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化单色仪并执行回零。",
      "description_en": "Initialize the monochromator and perform homing."
    },
    {
      "action_name": "auto-is_initialized",
      "description": "检查单色仪是否已完成初始化。",
      "description_en": "Check whether the monochromator has been initialized."
    },
    {
      "action_name": "auto-configuration",
      "description": "读取单色仪配置。",
      "description_en": "Read the monochromator configuration."
    },
    {
      "action_name": "auto-calibrate_wavelength",
      "description": "校准当前光栅位置对应的波长值。",
      "description_en": "Calibrate the wavelength value at the current grating position."
    },
    {
      "action_name": "auto-move_to_target_wavelength",
      "description": "将单色仪移动到目标波长。",
      "description_en": "Move the monochromator to the target wavelength."
    },
    {
      "action_name": "auto-set_turret_grating",
      "description": "设置转塔光栅。",
      "description_en": "Set the turret grating."
    },
    {
      "action_name": "auto-set_filter_wheel_position",
      "description": "设置滤光轮位置。",
      "description_en": "Set the filter wheel position."
    },
    {
      "action_name": "auto-set_mirror_position",
      "description": "设置反射镜位置。",
      "description_en": "Set the mirror position."
    },
    {
      "action_name": "auto-set_slit_position",
      "description": "设置指定狭缝的位置（毫米）。",
      "description_en": "Set the selected slit position in millimeters."
    },
    {
      "action_name": "auto-set_slit_step_position",
      "description": "设置狭缝步进位置。",
      "description_en": "Set the slit step position."
    },
    {
      "action_name": "auto-open_shutter",
      "description": "打开快门。",
      "description_en": "Open the shutter."
    },
    {
      "action_name": "auto-close_shutter",
      "description": "关闭快门。",
      "description_en": "Close the shutter."
    }
  ],
  "tag_hints": [
    "monochromator",
    "spectroscopy",
    "wavelength selection",
    "diffraction grating",
    "slit control",
    "filter wheel",
    "optical shutter"
  ]
}

